use super::*;
use photocraft_engine::{doc::{Document, LayerId, PixelFormat, Rect, SampleType}, channel_cmds::ChannelTarget};
use photocraft_raster::Surface;
use serde_json::json;

#[derive(Clone,Copy)]
enum Plane{Pixels(LayerId),Mask(LayerId),Alpha,QuickMask}
fn surface(doc:&Document,target:Plane)->&Surface{match target{Plane::Pixels(id)=>doc.layer(id).unwrap().surface().unwrap(),Plane::Mask(id)=>&doc.layer(id).unwrap().mask.as_ref().unwrap().surface,Plane::Alpha=>&doc.channels[1].surface,Plane::QuickMask=>&doc.quick_mask.as_ref().unwrap().surface}}
fn surface_mut(doc:&mut Document,target:Plane)->&mut Surface{match target{Plane::Pixels(id)=>doc.layer_mut(id).unwrap().surface_mut().unwrap(),Plane::Mask(id)=>&mut doc.layer_mut(id).unwrap().mask.as_mut().unwrap().surface,Plane::Alpha=>&mut doc.channels[1].surface,Plane::QuickMask=>&mut doc.quick_mask.as_mut().unwrap().surface}}
fn run(engine:&mut Session,command:&str,params:Value)->Result<Value,String>{super::super::execute_view_command(engine,command,params)}
fn twin(engine:&Session)->Session{let mut copy=Session::new();copy.add_document((*engine.active().unwrap().doc).clone(),None);*copy.active_mut().unwrap()=engine.active().unwrap().clone();copy.tools=engine.tools.clone();copy.presets=engine.presets.clone();copy.patterns=engine.patterns.clone();copy.journal=engine.journal.clone();copy.edit_state=engine.edit_state.clone();copy}
fn fixture(depth:u32,kind:&str,explicit:bool)->(Session,Plane,Value){
    let mut engine=Session::new();engine.execute("file.new",json!({"width":24,"height":20,"depth":depth,"background":"#4080b0"})).unwrap();let layer=engine.active().unwrap().active_layer.unwrap();engine.execute("layer.layerMask.revealAll",json!({})).unwrap();for name in ["Donor","Target"]{engine.execute("channel.new",json!({"name":name})).unwrap();}
    let target=match kind{"pixels"=>Plane::Pixels(layer),"mask"=>Plane::Mask(layer),"alpha"=>Plane::Alpha,_=>{engine.execute("select.editInQuickMaskMode",json!({})).unwrap();Plane::QuickMask}};
    engine.edit("Channel transaction planes",|doc,_|{let values:Vec<_>=(0..480).map(|index|0.05+(index%17)as f32/20.0).collect();doc.channels[0].surface.write_region(Rect::from_xywh(0,0,24,20),&values);if !matches!(target,Plane::Pixels(_)){let format=PixelFormat{sample:doc.depth,..PixelFormat::GRAY8};let mut coverage=Surface::with_default(format,&[1.0]);coverage.fill_rect(Rect::from_xywh(0,0,24,20),&[0.2]);coverage.write_pixel(-2,3,&[0.45]);*surface_mut(doc,target)=coverage;}let mut selection=Surface::new(PixelFormat::GRAY8);selection.fill_rect(Rect::from_xywh(3,3,18,14),&[0.7]);doc.selection=Some(selection);Ok(())}).unwrap();
    engine.execute("channel.target",json!({"channel":"composite"})).unwrap();if !explicit{match target{Plane::Mask(_)=>{engine.execute("view.layerMask",json!({"mode":"gray"})).unwrap();},Plane::Alpha=>{engine.execute("channel.target",json!({"channel":1})).unwrap();},_=>{}}}
    let mut params=json!({"source":{"channel":0},"blending":"normal","opacity":65});if explicit||matches!(target,Plane::Pixels(_)){params["target"]=match target{Plane::Pixels(_)=>json!("pixels"),Plane::Mask(_)=>json!("mask"),Plane::Alpha=>json!({"channel":1}),Plane::QuickMask=>json!("quickMask")};}(engine,target,params)
}
fn endpoints(engine:&Session,source:&DocState,target:Plane){let bounds=Rect::from_xywh(-3,-2,30,26);let before=surface(&source.doc,target).read_region(bounds);let painted=engine.active().unwrap().doc.clone();let after=surface(&painted,target).read_region(bounds);assert_ne!(before,after);for opacity in [0.0,50.0,100.0]{let mut faded=twin(engine);run(&mut faded,"edit.fade",json!({"opacity":opacity,"mode":"normal"})).unwrap();let current=faded.active().unwrap();let plane=surface(&current.doc,target);let tolerance=match plane.format().sample{SampleType::U8=>1.01/255.0,SampleType::U16=>1.01/65535.0,SampleType::F32=>0.000001};for((before,after),actual)in before.iter().zip(&after).zip(plane.read_region(bounds)){assert!((actual-(before+(after-before)*(opacity as f32/100.0))).abs()<=tolerance);}let mut restored=(*current.doc).clone();*surface_mut(&mut restored,target)=surface(&source.doc,target).clone();assert_eq!(&restored,source.doc.as_ref());run(&mut faded,"edit.undo",json!({})).unwrap();assert_eq!(faded.active().unwrap().doc,painted);run(&mut faded,"edit.undo",json!({})).unwrap();assert_eq!(faded.active().unwrap().doc,source.doc);run(&mut faded,"edit.redo",json!({})).unwrap();assert_eq!(faded.active().unwrap().doc,painted);}}
fn apply_oracle(engine:&Session,source:&DocState,target:Plane){let before=surface(&source.doc,target);let current=surface(&engine.active().unwrap().doc,target);let tolerance=match current.format().sample{SampleType::U8=>1.01/255.0,SampleType::U16=>1.01/65535.0,SampleType::F32=>0.000001};for y in 0..20{for x in 0..24{let donor=source.doc.channels[0].surface.sample_channel(x,y,0);let weight=0.65*source.doc.selection.as_ref().unwrap().sample_channel(x,y,0);for channel in 0..(if matches!(target,Plane::Pixels(_)){3}else{1}){let original=before.sample_channel(x,y,channel);let expected=original+(donor-original)*weight;assert!((current.sample_channel(x,y,channel)-expected).abs()<=tolerance);}}}}

#[test]
fn apply_image_shared_transaction_fades_pixels_and_coverage_and_keeps_raw_parameters(){
    for depth in [8,16,32]{for kind in ["pixels","mask","alpha","quickMask"]{for explicit in [false,true]{let(mut engine,target,mut params)=fixture(depth,kind,explicit);if matches!(target,Plane::Pixels(_)){engine.execute("channel.target",json!({"channel":1})).unwrap();}params["__xdesignChannelFade"]=json!({"revision":999});let source=engine.active().unwrap().clone();let journal=engine.journal.len();let mut native=twin(&engine);if matches!(target,Plane::Pixels(_)){native.execute("image.applyImage",params.clone()).unwrap();}run(&mut engine,"image.applyImage",params.clone()).unwrap();assert_eq!(engine.journal.len(),journal+1);assert_eq!(engine.journal.last().unwrap().1["source"],params["source"]);assert_eq!(engine.active().unwrap().history.past_len(),source.history.past_len()+1);if matches!(target,Plane::Pixels(_)){assert!(!engine.edit_state.fade.as_ref().unwrap().mask);assert_eq!(engine.active().unwrap().doc,native.active().unwrap().doc);}apply_oracle(&engine,&source,target);assert!(super::super::mask_filters::can_fade(&engine)||engine.is_enabled("edit.fade"));endpoints(&engine,&source,target);}}}
}

#[test]
fn pixel_fill_aliases_and_apply_image_keep_group_start_and_actual_layer(){
    for depth in [8,16,32]{for command in ["edit.fillForeground","edit.fillBackground","edit.fillForegroundPreserve","edit.fillBackgroundPreserve"]{
        let(mut engine,target,_)=fixture(depth,"pixels",true);engine.execute("channel.target",json!({"channel":1})).unwrap();let source=engine.active().unwrap().clone();let params=json!({"target":"pixels","coalesce":"pixel-alias","color":"#ff0000","opacity":2,"preserveTransparency":false});let mut native=twin(&engine);native.execute(command,params.clone()).unwrap();run(&mut engine,command,params.clone()).unwrap();assert_eq!(engine.active().unwrap().doc,native.active().unwrap().doc);assert!(engine.is_enabled("edit.fade"));assert!(!engine.edit_state.fade.as_ref().unwrap().mask);endpoints(&engine,&source,target);let label=engine.active().unwrap().history.undo_label().unwrap().to_owned();run(&mut engine,"image.applyImage",json!({"target":"pixels","source":{"channel":0},"opacity":50,"coalesce":"pixel-alias"})).unwrap();assert_eq!(engine.active().unwrap().history.past_len(),source.history.past_len()+1);assert_eq!(engine.edit_state.fade.as_ref().unwrap().label,label);endpoints(&engine,&source,target);
    }}
    let(mut engine,target,_)=fixture(16,"pixels",true);let Plane::Pixels(id)=target else{unreachable!()};engine.execute("layer.new.layer",json!({"name":"Unrelated active layer"})).unwrap();engine.execute("channel.target",json!({"channel":1})).unwrap();let source=engine.active().unwrap().clone();run(&mut engine,"edit.fillForeground",json!({"target":"pixels","layer":id.0})).unwrap();assert_eq!(engine.active().unwrap().active_layer,source.active_layer);assert_eq!(engine.edit_state.fade.as_ref().unwrap().layer,id);endpoints(&engine,&source,target);
}

#[test]
fn inactive_explicit_pixel_fill_and_patch_keep_native_pixels_and_correct_fade_source(){
    for depth in [8,16,32]{for(command,explicit)in [("edit.fill",true),("paint.patch",true),("paint.patch",false)]{let(mut engine,target,_)=fixture(depth,"pixels",true);let Plane::Pixels(layer)=target else{unreachable!()};engine.edit("Pixel patch donor",|doc,_|{let surface=surface_mut(doc,target);for y in 0..20{for x in 0..24{let value=((x*13+y*7)%17)as f32/20.0;surface.write_pixel(x,y,&[value,0.2+value/2.0,0.8-value/2.0,1.0]);}}Ok(())}).unwrap();engine.execute("layer.new.layer",json!({"name":"Unrelated active layer"})).unwrap();engine.execute("channel.target",json!({"channel":1})).unwrap();let source=engine.active().unwrap().clone();let mut params=if command=="edit.fill"{json!({"target":"pixels","layer":layer.0,"color":"#e0d0c0"})}else{json!({"layer":layer.0,"offset":[2,0]})};if explicit{params["target"]=json!("pixels");}let mut native=twin(&engine);native.execute(command,params.clone()).unwrap();run(&mut engine,command,params).unwrap();assert_eq!(engine.active().unwrap().doc,native.active().unwrap().doc);assert_eq!(engine.active().unwrap().active_layer,source.active_layer);assert_eq!(engine.edit_state.fade.as_ref().unwrap().layer,layer);assert!(!engine.edit_state.fade.as_ref().unwrap().mask);endpoints(&engine,&source,target);}}
}

#[test]
fn active_fill_patch_and_apply_image_groups_keep_first_pixel_or_mask_history_label(){
    for kind in ["pixels","mask"]{for first in ["edit.fill","paint.patch"]{let(mut engine,target,apply)=fixture(16,kind,true);engine.edit("Mixed group donor",|doc,_|{let plane=surface_mut(doc,target);for y in 0..20{for x in 0..24{let value=((x*13+y*7)%17)as f32/20.0;if matches!(target,Plane::Pixels(_)){plane.write_pixel(x,y,&[value,0.2+value/2.0,0.8-value/2.0,1.0]);}else{plane.write_pixel(x,y,&[value]);}}}Ok(())}).unwrap();let source=engine.active().unwrap().clone();let target_param=apply["target"].clone();let first_params=if first=="edit.fill"{json!({"target":target_param,"color":"#d0d0d0","coalesce":"mixed-apply"})}else{json!({"target":target_param,"offset":[2,0],"coalesce":"mixed-apply"})};run(&mut engine,first,first_params).unwrap();let label=engine.active().unwrap().history.undo_label().unwrap().to_owned();let mut params=apply;params["coalesce"]=json!("mixed-apply");run(&mut engine,"image.applyImage",params).unwrap();assert_eq!(engine.active().unwrap().history.past_len(),source.history.past_len()+1);assert_eq!(engine.edit_state.fade.as_ref().unwrap().label,label);endpoints(&engine,&source,target);}}
}

#[test]
fn structural_channel_edits_journal_and_coalesce_without_fade_and_refuse_atomically(){
    for depth in [8,16,32]{let(mut engine,_,_)=fixture(depth,"alpha",false);let source=engine.active().unwrap().clone();let count=engine.journal.len();for _ in 0..2{run(&mut engine,"image.calculations",json!({"source1":{"channel":0},"source2":{"channel":1},"result":"newChannel","coalesce":"channel-group"})).unwrap();}assert_eq!(engine.active().unwrap().doc.channels.len(),4);assert_eq!(engine.active().unwrap().history.past_len(),source.history.past_len()+1);assert_eq!(engine.journal.len(),count+4);assert_eq!(engine.journal[count].0,"image.calculations");assert_eq!(engine.journal[count+1].0,"channel.target");assert!(!super::super::mask_filters::can_fade(&engine));assert!(!engine.is_enabled("edit.fade"));run(&mut engine,"edit.undo",json!({})).unwrap();assert_eq!(engine.active().unwrap().doc,source.doc);run(&mut engine,"edit.redo",json!({})).unwrap();assert_eq!(engine.active().unwrap().doc.channels.len(),4);
        let source=engine.active().unwrap().clone();let count=engine.journal.len();run(&mut engine,"image.calculations",json!({"source1":{"channel":0},"source2":{"channel":1},"result":"selection","coalesce":"selection-group"})).unwrap();run(&mut engine,"select.loadSelection",json!({"channel":0,"operation":"add","coalesce":"selection-group"})).unwrap();assert_eq!(engine.active().unwrap().history.past_len(),source.history.past_len()+1);assert_eq!(engine.journal.len(),count+2);assert!(!engine.is_enabled("edit.fade"));run(&mut engine,"edit.undo",json!({})).unwrap();assert_eq!(engine.active().unwrap().doc,source.doc);
        for(command,params)in [("image.applyImage",json!({"source":{"channel":999}})),("image.calculations",json!({"result":"bad"})),("select.loadSelection",json!({"channel":0,"operation":"bad"}))]{let before=engine.active().unwrap().clone();let journal=engine.journal.clone();assert!(run(&mut engine,command,params).is_err());assert!(std::sync::Arc::ptr_eq(&before.doc,&engine.active().unwrap().doc));assert_eq!(engine.active().unwrap().coalesce,before.coalesce);assert_eq!(engine.journal,journal);}
        let before=engine.active().unwrap().doc.clone();let count=engine.journal.len();let result=channels::execute_checked(&mut engine,"image.calculations",&json!({"source1":{"channel":0},"source2":{"channel":1},"result":"newDocument"}),true).unwrap().unwrap();assert_eq!(result["document"],1);assert!(std::sync::Arc::ptr_eq(&engine.documents()[0].doc,&before));assert_eq!(engine.journal.len(),count+1);assert_eq!(engine.active().unwrap().history.past_len(),0);assert!(!engine.is_enabled("edit.fade"));
    }
}

fn workspace_step(resident:Session,donor:&Session,current:&PhotoReference,foreign:&PhotoReference,params:Value)->Session{
    let captured=resident.active().unwrap().clone();let(mut draft,translated)=prepare(&captured,&params,current,|reference|{assert_eq!(reference.photo_id,foreign.photo_id);assert_eq!(reference.version,foreign.version);Ok(donor.active().unwrap().clone())}).unwrap();channels::execute_checked(&mut draft,"image.applyImage",&translated,true).unwrap().unwrap();let journal=stable_journal(&draft,"image.applyImage",&params).unwrap();assert_eq!(journal[0].1["source"]["document"],params["source"]["document"]);assert_ne!(journal[0].1["__xdesignChannelFade"]["revision"],json!(999));validate_install(&resident,&captured).unwrap();let mut target=Session::new();target.add_document((*draft.documents()[0].doc).clone(),None);*target.active_mut().unwrap()=draft.documents()[0].clone();target.journal=journal;target.edit_state.fade=draft.edit_state.fade.clone();let prior=resident.journal.clone();let tools=resident.tools.brush.clone();let clone_sources=resident.presets.clone.clone();let mut response=json!({});retain_reply_tools(&mut response,&resident);assert_eq!(response["brush"],super::super::tools::inspect(&resident));assert_eq!(response["tools"],super::super::tools::colors(&resident));assert_eq!(response["presets"],super::super::tools::presets(&resident));install_context(&mut target,resident);assert_eq!(target.documents().len(),1);assert_eq!(&target.journal[..prior.len()],prior.as_slice());assert_eq!(target.tools.brush,tools);assert_eq!(target.presets.clone,clone_sources);target
}

#[test]
fn workspace_apply_preserves_stable_donors_resident_context_grouping_and_fade(){
    for depth in [8,16,32]{let(mut engine,target,_)=fixture(depth,"alpha",false);let(donor,_,_)=fixture(depth,"alpha",false);let donor_before=donor.active().unwrap().doc.clone();engine.tools.brush.size=31.0;engine.tools.foreground=[0.8,0.7,0.6,1.0];engine.presets.clone.active_mut().source=Some([4.0,5.0]);let source=engine.active().unwrap().clone();run(&mut engine,"edit.fillForeground",json!({"coalesce":"workspace-group"})).unwrap();let label=engine.active().unwrap().history.undo_label().unwrap().to_owned();let current=PhotoReference{photo_id:ulid::Ulid::new().to_string(),version:ulid::Ulid::new().to_string()};let foreign=PhotoReference{photo_id:ulid::Ulid::new().to_string(),version:ulid::Ulid::new().to_string()};for _ in 0..2{let params=json!({"source":{"document":{"photoId":foreign.photo_id,"version":foreign.version},"channel":0},"opacity":65,"coalesce":"workspace-group","__xdesignChannelFade":{"revision":999}});engine=workspace_step(engine,&donor,&current,&foreign,params);assert_eq!(engine.active().unwrap().history.past_len(),source.history.past_len()+1);assert_eq!(engine.active().unwrap().history.undo_label(),Some(label.as_str()));assert!(super::super::mask_filters::can_fade(&engine));}endpoints(&engine,&source,target);assert!(std::sync::Arc::ptr_eq(&donor_before,&donor.active().unwrap().doc));}
}

#[test]
fn workspace_install_refuses_changed_current_context_before_resident_mutation(){
    let(engine,_,_)=fixture(16,"alpha",false);let captured=engine.active().unwrap().clone();validate_install(&engine,&captured).unwrap();for mutation in ["allocation","revision","layer","selected","anchor","view","coalesce"]{let mut changed=twin(&engine);match mutation{"allocation"=>changed.active_mut().unwrap().doc=std::sync::Arc::new((*captured.doc).clone()),"revision"=>changed.active_mut().unwrap().revision+=1,"layer"=>changed.active_mut().unwrap().active_layer=None,"selected"=>changed.active_mut().unwrap().selected_layers.clear(),"anchor"=>changed.active_mut().unwrap().layer_anchor=None,"view"=>changed.active_mut().unwrap().channel_view.target=ChannelTarget::Composite,_=>changed.active_mut().unwrap().coalesce=Some("other".into())}let before=changed.active().unwrap().clone();let journal=changed.journal.clone();assert!(validate_install(&changed,&captured).is_err(),"{mutation}");assert!(std::sync::Arc::ptr_eq(&before.doc,&changed.active().unwrap().doc));assert_eq!(changed.journal,journal);}
    let current=PhotoReference{photo_id:ulid::Ulid::new().to_string(),version:ulid::Ulid::new().to_string()};assert!(prepare(&captured,&json!({"source":{"document":1}}),&current,|_|panic!("must refuse first")).is_err());assert_eq!(engine.active().unwrap().doc,captured.doc);assert!(stable_journal(&Session::new(),"image.applyImage",&json!({})).is_err());
}

#[test]
fn workspace_structural_results_keep_stable_context_without_restoring_old_fade(){
    for result in ["newChannel","selection","newDocument"]{
        let(mut resident,_,_)=fixture(16,"alpha",false);run(&mut resident,"edit.fillForeground",json!({})).unwrap();assert!(super::super::mask_filters::can_fade(&resident));let captured=resident.active().unwrap().clone();let(donor,_,_)=fixture(16,"alpha",false);let donor_before=donor.active().unwrap().doc.clone();let current=PhotoReference{photo_id:ulid::Ulid::new().to_string(),version:ulid::Ulid::new().to_string()};let foreign=PhotoReference{photo_id:ulid::Ulid::new().to_string(),version:ulid::Ulid::new().to_string()};let params=json!({"source1":{"document":{"photoId":foreign.photo_id,"version":foreign.version},"channel":0},"source2":{"channel":1},"result":result,"__xdesignChannelFade":{"revision":999}});let(mut draft,translated)=prepare(&captured,&params,&current,|_|Ok(donor.active().unwrap().clone())).unwrap();channels::execute_checked(&mut draft,"image.calculations",&translated,true).unwrap().unwrap();let context=stable_journal(&draft,"image.calculations",&params).unwrap();assert_eq!(context[0].1["source1"],params["source1"]);assert!(context[0].1.get("__xdesignChannelFade").is_none());assert_eq!(context.len(),if result=="newChannel"{2}else{1});assert!(draft.edit_state.fade.is_none());let mut target=Session::new();let edited=if result=="newDocument"{draft.active().unwrap()}else{&draft.documents()[0]};target.add_document((*edited.doc).clone(),None);*target.active_mut().unwrap()=edited.clone();target.journal=context;
        if result!="newDocument"{validate_install(&resident,&captured).unwrap();install_context(&mut target,resident);run(&mut target,"edit.undo",json!({})).unwrap();assert_eq!(target.active().unwrap().doc,captured.doc);}else{assert!(std::sync::Arc::ptr_eq(&resident.active().unwrap().doc,&captured.doc));assert_eq!(target.active().unwrap().history.past_len(),0);}
        assert!(!super::super::mask_filters::can_fade(&target));assert!(!target.is_enabled("edit.fade"));assert!(std::sync::Arc::ptr_eq(&donor_before,&donor.active().unwrap().doc));
    }
}
